import{_ as d,C as t,o as l,c as n,E as o,a2 as c}from"./chunks/framework.BOeh4kYD.js";const i="/joinwell52/assets/context-authority-20260918/approval-arguments.figure.zh.svg",b=JSON.parse('{"title":"点了批准，程序执行的还是你看到的那些参数吗？","description":"","frontmatter":{"schema":"publication-candidate-article/v2","title":"点了批准，程序执行的还是你看到的那些参数吗？","date":"2026-09-18","published_date":"2026-09-18","column":"open-source-engineering","category":"daily","article_type":"experiment-report","edition":"research-center","research_question":"条件审批看到的参数，是否就是函数最终执行的参数？","summary":"我们把 OpenAI Agents Python v0.22.2 与 v0.22.3 放进同一组实验：默认值、类型转换和 validator 会不会让审批对象与执行对象分离？","cover":"/assets/context-authority-20260918/approval-arguments.cover-v1.png","language":"zh-CN","lifecycle":"Published","publication_authorized":true,"evidence_status":"固定版本原程序对照；范围见正文","pageClass":"context-authority-article"},"headers":[],"relativePath":"zh/research/2026-09-18-approval-saw-raw-tool-ran-prepared.md","filePath":"zh/research/2026-09-18-approval-saw-raw-tool-ran-prepared.md","lastUpdated":1789700812000}'),p={name:"zh/research/2026-09-18-approval-saw-raw-tool-ran-prepared.md"};function s(u,e,h,g,q,v){const a=t("ArticleCover"),r=t("ArticleTableScroll");return l(),n("div",null,[o(a,{image:"/assets/context-authority-20260918/approval-arguments.cover-v1.png",kicker:"开源工程观察 · 版本对照实验",title:"点了批准，程序执行的还是你看到的那些参数吗？",summary:"默认值、类型转换和 validator，可能在批准之后悄悄改变真正的动作。",version:"2026-09-18",languageHref:"/en/research/2026-09-18-approval-saw-raw-tool-ran-prepared",languageLabel:"English"}),o(r,{language:"zh"}),e[0]||(e[0]=c('<h1 id="点了批准-程序执行的还是你看到的那些参数吗" tabindex="-1">点了批准，程序执行的还是你看到的那些参数吗？ <a class="header-anchor" href="#点了批准-程序执行的还是你看到的那些参数吗" aria-label="Permalink to &quot;点了批准，程序执行的还是你看到的那些参数吗？&quot;">​</a></h1><p>一位 Agent 准备调用工具。审批程序看到的是空对象 <code>{}</code>，判断没有危险，于是放行。</p><p>真正进入函数时，参数却已经变成了 <code>target=&quot;protected&quot;</code>。</p><p>这不是 Agent 偷换了参数。变化发生在更普通的地方：参数模型自动补上了默认值。类似的变化还可能来自类型转换，例如字符串 <code>&quot;1&quot;</code> 变成整数 <code>1</code>；也可能来自应用 validator，把 <code>PROD</code> 规范成 <code>prod</code>。</p><p>于是，一个容易被忽略的问题出现了：<strong>审批程序批准的对象，与函数最终执行的对象，是不是同一个？</strong></p><h2 id="为什么我们会追这个问题" tabindex="-1">为什么我们会追这个问题 <a class="header-anchor" href="#为什么我们会追这个问题" aria-label="Permalink to &quot;为什么我们会追这个问题&quot;">​</a></h2><p>OpenAI Agents Python 在 2026 年 9 月 17 日合并了 <a href="https://github.com/openai/openai-agents-python/pull/5066" target="_blank" rel="noreferrer">PR #5066</a>，随后发布 v0.22.3。维护者 Kazuhiro Sera 说明，条件审批回调过去可能检查与 Python 函数实际使用不同的参数；新版本会先准备参数，并在验证改变参数时要求人工审批。</p><p>这个改动引起我们的兴趣，因为它把一个抽象的治理问题变成了可以复验的执行路径：原始 JSON 进入工具以后，先被谁解释，审批发生在解释之前还是之后，最终副作用又使用哪一份值？</p><p>我们没有只复述修复说明，而是把 v0.22.2 和 v0.22.3 放进同一组实验。</p><h2 id="六个用例-只有一件事不同" tabindex="-1">六个用例，只有一件事不同 <a class="header-anchor" href="#六个用例-只有一件事不同" aria-label="Permalink to &quot;六个用例，只有一件事不同&quot;">​</a></h2><p>实验使用两个固定源码版本：v0.22.2 的提交 <code>83c737f</code>，以及 v0.22.3 的提交 <code>fdf21db</code>。每次都通过原项目的 <code>Runner</code>、装饰器工具、<code>ScriptedModel</code> 和真实工具执行路径运行。</p><p>我们没有调用在线模型，也没有写入外部系统。脚本只记录审批回调看到什么、是否出现人工审批中断，以及函数体最终收到什么。</p><table tabindex="0"><thead><tr><th>用例</th><th>原始参数</th><th>验证后的参数</th></tr></thead><tbody><tr><td>原样安全目标</td><td><code>{&quot;target&quot;:&quot;safe&quot;}</code></td><td>不变</td></tr><tr><td>原样受保护目标</td><td><code>{&quot;target&quot;:&quot;protected&quot;}</code></td><td>不变</td></tr><tr><td>缺省默认目标</td><td><code>{}</code></td><td><code>{&quot;target&quot;:&quot;protected&quot;}</code></td></tr><tr><td>显式整数</td><td><code>{&quot;count&quot;:1}</code></td><td>不变</td></tr><tr><td>字符串转整数</td><td><code>{&quot;count&quot;:&quot;1&quot;}</code></td><td><code>{&quot;count&quot;:1}</code></td></tr><tr><td>应用 validator</td><td><code>{&quot;environment&quot;:&quot;PROD&quot;}</code></td><td><code>{&quot;environment&quot;:&quot;prod&quot;}</code></td></tr></tbody></table><h2 id="旧版本里-批准与执行确实可能错位" tabindex="-1">旧版本里，批准与执行确实可能错位 <a class="header-anchor" href="#旧版本里-批准与执行确实可能错位" aria-label="Permalink to &quot;旧版本里，批准与执行确实可能错位&quot;">​</a></h2><p>在 v0.22.2 中，完全相同的参数符合直觉：安全目标执行，受保护目标触发审批。</p><p>真正的差别出现在验证改变参数时：</p><ul><li>空对象进入条件回调时仍是 <code>{}</code>，回调放行；函数收到默认补出的 <code>protected</code> 并执行。</li><li>回调看到字符串 <code>&quot;1&quot;</code>，函数收到整数 <code>1</code>。</li><li>回调看到 <code>PROD</code>，函数收到 validator 转换后的 <code>prod</code>。</li></ul><p>也就是说，条件回调并没有看到函数实际消费的完整对象。</p><p><img src="'+i+'" alt="v0.22.2 与 v0.22.3 对验证后参数的不同处理"></p><p><em>图 1：v0.22.2 的条件回调读取原始参数，函数消费验证后参数；v0.22.3 遇到值变化时转入人工审批。图中是本轮六用例的概括，不代表所有 schema 行为。</em></p><h2 id="新版本选择了一个保守边界" tabindex="-1">新版本选择了一个保守边界 <a class="header-anchor" href="#新版本选择了一个保守边界" aria-label="Permalink to &quot;新版本选择了一个保守边界&quot;">​</a></h2><p>在 v0.22.3 中，原样参数仍沿用条件回调：安全目标继续执行，受保护目标继续中断。默认值、类型转换和 validator 造成的三种变化，则都没有调用条件回调，而是直接进入人工审批，函数没有执行。</p><p>这不是简单地把审批放到“验证之后”。如果直接把转换后的值送给原有条件回调，也可能改变应用过去依赖的策略语义。新版本采用了更保守的兼容方式：<strong>原始值与准备后值能安全证明一致，才继续走原条件规则；发生变化时，把决定交还给人。</strong></p><p>我们还运行了 v0.22.3 新增的审批参数测试文件，108 条测试全部通过。</p><h2 id="批准一个工具名-还远远不够" tabindex="-1">批准一个工具名，还远远不够 <a class="header-anchor" href="#批准一个工具名-还远远不够" aria-label="Permalink to &quot;批准一个工具名，还远远不够&quot;">​</a></h2><p>这组实验让“批准”变得更具体。一次可验证的批准，至少需要回答：</p><ol><li>人或策略看到了哪份参数？</li><li>schema 默认值和 validator 已经运行了吗？</li><li>实际执行前，参数是否仍与获批对象一致？</li><li>恢复 session 后，继续执行的是否仍是同一个准备后动作？</li></ol><p>如果界面只显示工具名，例如“允许调用 deploy”，用户仍然不知道目标环境是原始的 <code>PROD</code>、规范化后的 <code>prod</code>，还是默认补出的另一个值。更可靠的审批记录，应把最终动作绑定到可复验的摘要，并在动作变化时让旧批准失效。</p><h2 id="codeflowmu-要不要因此改代码" tabindex="-1">CodeFlowMu 要不要因此改代码 <a class="header-anchor" href="#codeflowmu-要不要因此改代码" aria-label="Permalink to &quot;CodeFlowMu 要不要因此改代码&quot;">​</a></h2><p>我们检查了 CodeFlowMu v2.1.2 的本地实现。它会为审批请求计算稳定的 <code>operation_digest</code>，执行前再用当前请求重算；摘要变化会把记录标成 <code>stale</code> 并拒绝执行。它还绑定 operation fingerprint、项目、Agent、任务、thread 和角色，并使用一次性 execution token。本轮 28 条审批边界定向测试全部通过。</p><p>因此，本轮结论是 <strong>不进入开发</strong>。这不代表永远不需要改，而是目前没有发现“审批对象与执行对象漂移”的本地证据。研究结果进入文章和后续审查清单，不应自动变成开发任务。</p><h2 id="还没有被回答的问题" tabindex="-1">还没有被回答的问题 <a class="header-anchor" href="#还没有被回答的问题" aria-label="Permalink to &quot;还没有被回答的问题&quot;">​</a></h2><p>OpenAI Agents Python 的改动解决了一个明确版本中的参数错位，也留下了更值得专业读者讨论的问题：</p><ul><li>审批界面应该只显示准备后的参数，还是同时显示原始值与转换差异？</li><li>如果 validator 依赖时间、外部状态或自定义代码，准备结果能否稳定重放？</li><li>人批准一次准备后的动作，恢复运行时应重新准备并比较，还是保存并执行当时的快照？</li><li>面对无法安全比较的对象，强制人工审批已经足够，还是还应禁止执行？</li></ul><p>对普通使用者，判断可以更直接：<strong>你点下“批准”以后，是否能说清程序最终会拿哪些值做什么？</strong> 如果不能，审批仍然只是一个按钮，还不是执行证据。</p><h2 id="实验资料" tabindex="-1">实验资料 <a class="header-anchor" href="#实验资料" aria-label="Permalink to &quot;实验资料&quot;">​</a></h2><ul><li><a href="https://github.com/openai/openai-agents-python/pull/5066" target="_blank" rel="noreferrer">OpenAI Agents Python PR #5066</a></li><li><a href="https://github.com/openai/openai-agents-python/releases/tag/v0.22.3" target="_blank" rel="noreferrer">v0.22.3 Release</a></li><li><a href="https://github.com/joinwell52-AI/joinwell52/tree/main/research/manual-runs/2026-09-18-context-authority" target="_blank" rel="noreferrer">本轮公开实验记录</a></li></ul>',37))])}const _=d(p,[["render",s]]);export{b as __pageData,_ as default};
